<?php require_once __DIR__.'/../app/bootstrap.php'; requireLogin(); $action=$_POST['action']??''; $postId=rawurlencode($_POST['post_id']??''); if($action==='like') $r=apiRequest('POST',"/api/v1/posts/$postId/like",[]); elseif($action==='comment') $r=apiRequest('POST',"/api/v1/posts/$postId/comments",['content'=>trim($_POST['content']??'')]); elseif($action==='friend') $r=apiRequest('POST','/api/v1/friends',['target_user_id'=>$_POST['target_user_id']??'']); else $r=['ok'=>false,'message'=>'Thao tác không hợp lệ']; flash($r['ok']?'success':'error',$r['ok']?'Thao tác thành công.':$r['message']); header('Location: '.($_SERVER['HTTP_REFERER']??'feed.php')); exit;
